#!/usr/bin/env node
// The colour tokens of the embedded editor (design 025 E8): `src/styles.css` is the one source
// (the video export reads it too); this script turns its `:root`/`html`/`body` rules into
// `:host` rules for the shadow root of `<editlicious-editor>` – one instance, one scheme, no
// `:host-context()`, nothing on the page. `--check` fails when the generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('..', import.meta.url));
export const SOURCE = `${root}src/styles.css`;
export const TARGET = `${root}src/app/embed/host-theme.css`;

/** Top-level blocks of a stylesheet: `{ prelude, body }` (comments removed, nesting kept). */
export function blocks(css) {
  const text = css.replace(/\/\*[\s\S]*?\*\//g, '');
  const out = [];
  let i = 0;
  while (i < text.length) {
    const open = text.indexOf('{', i);
    if (open < 0) break;
    let depth = 1;
    let j = open + 1;
    for (; j < text.length && depth > 0; j++) {
      if (text[j] === '{') depth++;
      else if (text[j] === '}') depth--;
    }
    out.push({ prelude: text.slice(i, open).trim(), body: text.slice(open + 1, j - 1) });
    i = j;
  }
  return out;
}

/** One selector of `styles.css` → its shadow-root form; `null` = not for the embedded editor. */
export function hostSelector(sel) {
  const s = sel.trim();
  if (s.startsWith('[data-preview]') || s === 'html') return null;
  if (s === 'body') return ':host';
  if (s.startsWith(':root')) {
    const rest = s.slice(':root'.length);
    return rest ? `:host(${rest})` : ':host';
  }
  return s;
}

function rule(prelude, body) {
  if (prelude.startsWith('@')) {
    const inner = blocks(body)
      .map((b) => rule(b.prelude, b.body))
      .filter(Boolean)
      .join('\n');
    return inner ? `${prelude} {\n${inner}\n}` : '';
  }
  const sels = prelude.split(',').map((x) => x.trim());
  // `html, body { height: 100% }` is the page's, not the editor's
  if (sels.includes('html')) return '';
  const mapped = sels.map(hostSelector).filter(Boolean);
  if (!mapped.length) return '';
  return `${mapped.join(',\n')} {${body.replace(/\s+$/, '')}\n}`;
}

/** The generated stylesheet. */
export function hostTheme(css) {
  const rules = blocks(css)
    .map((b) => rule(b.prelude, b.body))
    .filter(Boolean);
  return [
    '/* Generated by scripts/host-theme.mjs from src/styles.css – do not edit (design 025 E8). */',
    ...rules,
    '',
  ].join('\n\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const want = hostTheme(readFileSync(SOURCE, 'utf8'));
  if (process.argv.includes('--check')) {
    let have = '';
    try {
      have = readFileSync(TARGET, 'utf8');
    } catch {
      // missing
    }
    if (have !== want) {
      console.error('src/app/embed/host-theme.css is stale – run `pnpm host-theme`');
      process.exit(1);
    }
  } else {
    writeFileSync(TARGET, want);
    console.log(`wrote ${TARGET}`);
  }
}
